    // ------------------------------------------------------------------------
    // Convenience Functions from easy_usage.md
    // ------------------------------------------------------------------------
    
    m.def("run_simulation", [](std::shared_ptr<nlm::Brain> brain, 
                              std::shared_ptr<nlm::SimpleWorld> world,
                              std::shared_ptr<nlm::AgentBrain> agent,
                              size_t num_steps) {
        for (size_t step = 0; step < num_steps; ++step) {
            world->update(0.1);
            agent->processSensoryInput(world->getSensoryPercept());
            brain->step(static_cast<nlm::SimulationStep>(step));
            world->applyMotorCommand(agent->decodeMotorCommand(), world->getSimulationTime());
        }
    }, "Run complete agent simulation", py::arg("brain"), py::arg("world"),
        py::arg("agent"), py::arg("num_steps") = 1000);
    
    m.def("run_agent_simulation", [](std::shared_ptr<nlm::Config> config,
                                     size_t num_steps) {
        auto brain = std::make_shared<nlm::Brain>(config);
        brain->initialize();
        auto agent = std::make_shared<nlm::AgentBrain>(brain);
        auto world = std::make_shared<nlm::SimpleWorld>();
        world->configure(20, 20, 8, 8);
        world->reset();
        world->setAgentStart(10.0, 10.0);
        agent->initialize(*world);
        
        for (size_t step = 0; step < num_steps; ++step) {
            world->update(0.1);
            agent->processSensoryInput(world->getSensoryPercept());
            brain->step(static_cast<nlm::SimulationStep>(step));
            world->applyMotorCommand(agent->decodeMotorCommand(), world->getSimulationTime());
        }
    }, "Run complete agent simulation", py::arg("config"), py::arg("num_steps") = 1000);
    
    m.def("minimal_example", []() {
        auto config = std::make_shared<nlm::Config>();
        auto brain = std::make_shared<nlm::Brain>(config);
        brain->initialize();
        
        for (int i = 0; i < 100; ++i) {
            brain->step(i);
        }
        
        return "Simulation complete!";
    }, "Minimal example simulation");
    
    // ------------------------------------------------------------------------
